import { Box, Container, Link, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { ArrowForwardIcon } from "../../utils/iconMap";

export default function PartnersSection() {
  const { partners, sections } = masterData;

  return (
    <Box sx={{ py: { xs: 5, md: 7 } }}>
      <Container maxWidth="lg">
        <Stack
          direction="row"
          justifyContent="space-between"
          alignItems="center"
          sx={{ mb: 3 }}
        >
          <Typography
            variant="h4"
            sx={{ fontWeight: 800, color: "#0A2540", fontSize: { xs: "1.4rem", md: "2rem" } }}
          >
            {sections.partners.title}
          </Typography>
          <Link
            underline="none"
            href="#partners"
            sx={{
              display: "inline-flex",
              alignItems: "center",
              gap: 0.5,
              color: "primary.main",
              fontWeight: 600,
              fontSize: { xs: 13, md: 15 },
            }}
          >
            {sections.partners.viewAll} <ArrowForwardIcon sx={{ fontSize: 16 }} />
          </Link>
        </Stack>

        <Stack
          direction="row"
          flexWrap="wrap"
          useFlexGap
          spacing={2}
          justifyContent="space-between"
          alignItems="center"
        >
          {partners.map((partner) => (
            <Box
              key={partner.id}
              component="img"
              src={partner.logo}
              alt={partner.name}
              sx={{
                height: 48,
                width: { xs: "45%", sm: 120 },
                objectFit: "contain",
                opacity: 0.9,
                filter: "grayscale(0.2)",
              }}
            />
          ))}
        </Stack>
      </Container>
    </Box>
  );
}
